def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    opp_d = sum(1 for o in opp if o == 'D')

    if n >= 99:
        return 'D'

    if n >= 4 and opp_d > n * 0.6:
        return 'D'

    last_opp = opp[-1]
    if last_opp == 'C':
        return 'C'

    if opp_d <= n * 0.25:
        return 'C'

    recent = history[-4:] if n >= 4 else history
    for m, o in recent:
        if m == 'D' and o == 'C':
            return 'C'

    return 'D'
